    financial: { page: 'financial', patch: { fm: '2026-10', fs: 'efetivo', fc: 'todas' } },
    inventory: { page: 'inventory', patch: { iq: 'Milho', il: 'Armazém Primavera', isort: 'material' } },
    recipes: { page: 'recipes', patch: {} },
