function closeOverlay() { moduleOpen = ''; mobileOpen = false; render(); const target = document.getElementById(overlayRestoreId); if (target?.getClientRects().length) target.focus(); else if (frame.clientWidth <= 820) document.getElementById('mobile-menu-trigger')?.focus(); else (document.getElementById('local-module-trigger') || document.getElementById('rail-modules-trigger'))?.focus(); }
