document.getElementById('state-select').onchange = event => setDemonstrationState(event.target.value);
document.addEventListener('click', event => {
  const anchor = event.target.closest('a[href^="#"]');
  if (anchor && anchor.getAttribute('href') !== '#page-title') {
    if (event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return;
    event.preventDefault();
    let target = anchor.getAttribute('href');
    if (anchor.hasAttribute('data-direct-animal')) { const a = currentAnimal(); target = url(`animals/${a.id}/weight/1`, { device: q('device'), source: 'direct' }, true); }
    navigate(target); return;
  }
  const button = event.target.closest('button'); if (!button) return;
  if (button.hasAttribute('data-open-module')) { mobileOpen = false; moduleOpen = button.dataset.openModule; overlayRestoreId = button.id || 'local-module-trigger'; render(); }
  else if (button.hasAttribute('data-mobile-menu')) { mobileOpen = true; moduleOpen = ''; overlayRestoreId = 'mobile-menu-trigger'; render(); }
  else if (button.hasAttribute('data-close-overlay')) closeOverlay();
  else if (button.hasAttribute('data-close-panel')) closePanel();
  else if (button.hasAttribute('data-open-entry')) navigate(url('financial', { panel: 'detail', entry: button.dataset.openEntry }));
  else if (button.hasAttribute('data-edit-entry')) navigate(url('financial', { panel: 'edit' }));
  else if (button.hasAttribute('data-cancel-entry')) navigate(url('financial', { panel: 'detail' }));
  else if (button.hasAttribute('data-clear-animals')) navigate(url('animals', { aq: null, astatus: null, apage: 1, asort: 'nome' }));
  else if (button.hasAttribute('data-reset-state')) setDemonstrationState('normal');
  else if (button.hasAttribute('data-clear-current')) navigate(url(moduleId() === 'home' ? 'animals' : moduleId(), { state: null, aq: null, astatus: null, apage: 1, asort: 'nome', iq: null, il: null, isort: 'material', fs: 'todos', fc: 'todas' }));
  else if (button.hasAttribute('data-confirm-receive')) showDialog('Confirmar recebimento demonstrativo?', `<p>Confirme o recebimento de <strong>${e(q('qty', '100'))} kg de Milho grão</strong> no lote LOT-DEMO-01. Este é um exemplo visual; nenhum movimento real será criado.</p>`, [{ label: 'Continuar revisando', action: closeDialog }, { label: 'Confirmar recebimento', primary: true, action: () => { closeDialog(); navigate(url('inventory/event', { confirmed: 1 }), true); notify('Evento sintético exibido. Nenhum saldo real foi alterado.'); } }]);
  else if (button.hasAttribute('data-demo-confirm')) showDialog('Confirmação de ação', '<p>O comando deve informar seu efeito e exigir uma confirmação explícita. O foco volta ao controle de origem quando o diálogo fecha.</p>', [{ label: 'Cancelar', action: closeDialog }, { label: 'Confirmar demonstração', primary: true, action: () => { closeDialog(); notify('Confirmação demonstrada. Nenhum dado foi alterado.'); } }]);
  else if (button.hasAttribute('data-demo-action')) {
    const action = button.dataset.demoAction;
    if (action === 'conflict-current') showDialog('Consultar versão atual', '<p>A proposta mantém a edição e apresenta os dados atuais para comparação. A resolução real depende dos contratos existentes e deverá ser implementada após a escolha.</p>', [{ label: 'Voltar à minha edição', action: closeDialog }]);
    else showDialog('Destino existente · fora desta amostra', '<p>Esta ação existe no GenSW. O protótipo concentra a demonstração nos quatro contratos: lista/detalhe/edição, caixa/painel, estoque/comando e registro pai/filho. Nenhuma nova função está sendo criada aqui.</p>', [{ label: 'Continuar explorando', action: closeDialog }]);
  }
});
document.addEventListener('keydown', event => {
  if (dialog.open) return;
  const trap = app.querySelector('[data-focus-trap]'); if (!trap) return;
  if (event.key === 'Escape') { event.preventDefault(); if (moduleOpen || mobileOpen) closeOverlay(); else closePanel(); return; }
  if (event.key === 'Tab') {
    const focusable = [...trap.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]')].filter(el => el.getClientRects().length);
    const first = focusable[0], last = focusable.at(-1);
    if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
    else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
  }
});
window.addEventListener('hashchange', () => {
  const nextHash = location.hash;
  if (dirty && nextHash !== lastHash) { history.replaceState(null, '', lastHash); navigate(nextHash); return; }
  const next = parseRoute();
  const closingFinancialPanel = current.page === 'financial' && current.params.has('panel') && next.page === 'financial' && !next.params.has('panel');
  current = next; lastHash = location.hash; mobileOpen = false; moduleOpen = ''; render(true);
  if (closingFinancialPanel) document.getElementById('entry-' + q('entry', '1'))?.focus({ preventScroll: true });
});
window.addEventListener('beforeunload', event => { if (dirty) { event.preventDefault(); event.returnValue = ''; } });
if (!location.hash) { history.replaceState(null, '', '#a/home'); current = parseRoute(); lastHash = location.hash; }
render();
